// Package postgres is the reference [outbox.Store] for PostgreSQL 12 or later.
//
// It uses only database/sql, so it works with any PostgreSQL driver that
// registers one (lib/pq, jackc/pgx via pgx/stdlib). Claiming is done with a
// single `FOR UPDATE SKIP LOCKED` statement so that many workers can share one
// table without blocking each other, and every state change is fenced by a
// lease epoch so a worker that lost its lease cannot overwrite the new owner's
// state.
//
// All timestamps are generated by the database clock (now(), i.e. the
// transaction timestamp) and stored as timestamptz, so workers with skewed
// clocks cannot mis-expire each other's leases.
package postgres

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"regexp"
	"strconv"
	"strings"
	"time"

	"github.com/tahaNGU/gocast"
)

// DefaultTable is the table name used unless [WithTable] says otherwise.
const DefaultTable = "outbox_messages"

const (
	// maxRowsPerInsert is the default rows per INSERT statement: small enough
	// to plan quickly, large enough to amortise the round trip.
	maxRowsPerInsert = 500

	// MaxEnqueueBatch is the largest value [WithMaxEnqueueBatch] accepts:
	// 7281 rows. PostgreSQL allows 65535 bind parameters per statement and
	// this table binds nine per row, so beyond this the statement cannot be
	// sent at all.
	MaxEnqueueBatch = 65535 / enqueueColumns

	// enqueueColumns is the number of bind parameters per enqueued row.
	enqueueColumns = 9
)

// enqueueCasts is the SQL cast for each bind parameter of an enqueued row
// except the last (available_at), which needs an expression rather than a
// cast. Declaring it with an exact array length makes a mismatch with
// enqueueColumns a compile error.
var enqueueCasts = [enqueueColumns - 1]string{
	"::uuid", "", "::bytea", "", "::jsonb", "", "", "",
}

// DB is the subset of *sql.DB the store needs for its own queries: everything
// except enqueueing, which runs on the application's transaction instead.
// It is satisfied by *sql.DB, *sql.Conn and *sql.Tx.
type DB interface {
	ExecContext(ctx context.Context, query string, args ...any) (sql.Result, error)
	QueryContext(ctx context.Context, query string, args ...any) (*sql.Rows, error)
	QueryRowContext(ctx context.Context, query string, args ...any) *sql.Row
}

// Store is a PostgreSQL-backed outbox. Create it with [New]; it is safe for
// concurrent use and holds no state beyond its configuration and the handle it
// was given, which it never closes.
type Store struct {
	db       DB
	table    string
	prefix   string
	ordered  bool
	maxBatch int

	// Pre-rendered statements. The table name is validated once, at
	// construction, and every value is passed as a bind parameter.
	claimSQL      string
	publishSQL    string
	rescheduleSQL string
	failSQL       string
	releaseSQL    string
	stateSQL      string
	statsSQL      string
	pruneSQL      string
	listFailedSQL string
}

// Option configures a [Store].
type Option func(*Store) error

// WithTable overrides the table name, optionally schema-qualified
// ("app.outbox_messages"). Both parts must be simple SQL identifiers; anything
// else is rejected, so the name can never carry SQL into a statement.
func WithTable(name string) Option {
	return func(s *Store) error {
		table, prefix, err := parseTable(name)
		if err != nil {
			return err
		}
		s.table, s.prefix = table, prefix
		return nil
	}
}

// WithOrdering serialises delivery per [outbox.Message.OrderingKey]: a message
// is not claimed while an earlier message with the same key is unpublished.
//
// The guarantee, precisely:
//
//   - For a single ordering key, no two messages are ever in flight at the same
//     time under healthy leases, and attempt n+1 does not start before message
//     n is marked published. Within a key, publication order therefore follows
//     enqueue order (the seq column).
//   - It is per key only. Nothing is guaranteed about the relative order of
//     different keys, and there is no global ordering.
//   - It assumes writers to one key are serialised by the application (which a
//     row lock or an aggregate version check already does). Two concurrent
//     transactions writing the same key can commit in an order that does not
//     match their sequence numbers, and the outbox cannot see an uncommitted
//     row.
//   - A message that fails permanently blocks its key until an operator
//     requeues or deletes it. That is the point of ordered delivery, but it
//     means ordered keys need failure alerting.
//   - An expired lease can still produce a duplicate, and a duplicate can
//     arrive out of order relative to later messages for the same key.
//
// It requires the index in migration 0002, which [Store.Migrate] applies when
// this option is set.
//
// Cost: the blocking test is evaluated per candidate row, and the claim limit
// applies after it, so a claim walks past blocked rows looking for claimable
// ones. A key with a very long blocked backlog therefore makes claiming more
// expensive -- another reason to alert on failed messages when using ordered
// delivery.
func WithOrdering() Option {
	return func(s *Store) error {
		s.ordered = true
		return nil
	}
}

// WithMaxEnqueueBatch caps how many rows one INSERT statement carries.
// The default is 500, and the maximum is [MaxEnqueueBatch], which is what
// PostgreSQL's limit of 65535 bind parameters per statement allows for this
// table. Larger enqueues are split across several statements on the caller's
// transaction, so this only affects statement size, never atomicity.
func WithMaxEnqueueBatch(n int) Option {
	return func(s *Store) error {
		if n <= 0 || n > MaxEnqueueBatch {
			return fmt.Errorf("outbox/postgres: max enqueue batch must be between 1 and %d, got %d",
				MaxEnqueueBatch, n)
		}
		s.maxBatch = n
		return nil
	}
}

var identifier = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)

func parseTable(name string) (table, prefix string, err error) {
	parts := strings.Split(name, ".")
	if len(parts) > 2 {
		return "", "", fmt.Errorf("outbox/postgres: invalid table name %q", name)
	}
	for _, p := range parts {
		if !identifier.MatchString(p) {
			return "", "", fmt.Errorf("outbox/postgres: invalid table name %q: %q is not a plain SQL identifier", name, p)
		}
	}
	return strings.Join(parts, "."), parts[len(parts)-1], nil
}

// New returns a store that reads and writes the outbox table through db.
//
// db is used for the worker's own queries (claiming, acknowledging, stats,
// retention). Enqueueing does not use it: [Store.Enqueue] runs on the
// transaction the application passes in.
func New(db DB, opts ...Option) (*Store, error) {
	if db == nil {
		return nil, errors.New("outbox/postgres: db is required")
	}
	s := &Store{db: db, table: DefaultTable, prefix: DefaultTable, maxBatch: maxRowsPerInsert}
	for _, opt := range opts {
		if err := opt(s); err != nil {
			return nil, err
		}
	}
	s.render()
	return s, nil
}

// Table returns the table name the store operates on.
func (s *Store) Table() string { return s.table }

const claimedColumns = `m.id, m.event_type, m.payload, m.content_type, m.headers::text,
		m.aggregate_type, m.aggregate_id, m.ordering_key,
		m.created_at, due.prev_available_at, m.attempts, m.seq,
		m.lease_epoch, m.available_at, due.prev_state`

func (s *Store) render() {
	t := s.table

	// Ordered delivery adds one predicate: skip a keyed message while an
	// earlier message for the same key is still unpublished.
	ordering := ""
	if s.ordered {
		ordering = `
		   AND (m.ordering_key IS NULL OR NOT EXISTS (
		           SELECT 1 FROM ` + t + ` e
		            WHERE e.ordering_key = m.ordering_key
		              AND e.seq < m.seq
		              AND e.state <> 'published'))`
	}

	// One statement does everything: select the due rows under SKIP LOCKED,
	// take ownership, bump the attempt count and the fencing epoch, and return
	// the rows together with the state and availability they had beforehand
	// (so the worker can tell a fresh claim from a reclaimed lease, and can
	// measure how long the message waited).
	//
	// The predicate has a single branch because available_at means "when this
	// row may be taken" for pending and leased rows alike, which lets one
	// partial index serve the scan in order and the LIMIT end it early: no
	// sort, and no scan of published rows.
	//
	// AS MATERIALIZED is not optional. A locking sub-select that PostgreSQL is
	// free to re-evaluate can return more rows in total than its LIMIT allows;
	// materialising the CTE pins it to exactly one evaluation.
	s.claimSQL = `
WITH due AS MATERIALIZED (
	SELECT m.id,
	       m.state        AS prev_state,
	       m.available_at AS prev_available_at
	  FROM ` + t + ` m
	 WHERE m.state IN ('pending', 'leased')
	   AND m.available_at <= now()` + ordering + `
	 ORDER BY m.available_at, m.seq
	 LIMIT $1
	   FOR UPDATE SKIP LOCKED
)
UPDATE ` + t + ` m
   SET state        = 'leased',
       attempts     = m.attempts + 1,
       lease_epoch  = m.lease_epoch + 1,
       lease_owner  = $2,
       available_at = now() + make_interval(secs => $3),
       updated_at   = now()
  FROM due
 WHERE m.id = due.id
RETURNING ` + claimedColumns

	// Every mutation below is fenced: it applies only while this worker still
	// holds the lease it was given. A worker whose lease expired sees zero
	// rows affected and reports outbox.ErrLeaseLost rather than overwriting
	// the new owner's state.
	const fence = ` WHERE id = $1 AND lease_epoch = $2 AND state = 'leased'`

	s.publishSQL = `UPDATE ` + t + `
   SET state = 'published', published_at = now(), updated_at = now(),
       lease_owner = NULL, last_error = NULL, last_error_kind = NULL` + fence

	s.rescheduleSQL = `UPDATE ` + t + `
   SET state = 'pending', available_at = now() + make_interval(secs => $3),
       updated_at = now(), lease_owner = NULL,
       last_error = $4, last_error_kind = $5` + fence

	s.failSQL = `UPDATE ` + t + `
   SET state = 'failed', updated_at = now(), lease_owner = NULL,
       last_error = $3, last_error_kind = $4` + fence

	s.releaseSQL = `UPDATE ` + t + `
   SET state = 'pending', available_at = now(), updated_at = now(),
       lease_owner = NULL` + fence

	s.stateSQL = `SELECT state, lease_epoch FROM ` + t + ` WHERE id = $1`

	// Each count is served by a partial index, so the cost tracks the number
	// of rows in that state, not the size of the table; published rows are
	// never scanned. min(available_at) reads a single index entry.
	s.statsSQL = `SELECT
	(SELECT count(*) FROM ` + t + ` WHERE state = 'pending'),
	(SELECT count(*) FROM ` + t + ` WHERE state = 'leased'),
	(SELECT count(*) FROM ` + t + ` WHERE state = 'failed'),
	(SELECT min(available_at) FROM ` + t + ` WHERE state = 'pending'),
	now()`

	// Deleting is restricted to published rows in both the CTE that picks the
	// rows and the DELETE itself, so a mistake in one cannot touch an
	// undelivered message. AS MATERIALIZED keeps the batch limit honest: as a
	// plain IN (SELECT ... LIMIT n FOR UPDATE) sub-select, PostgreSQL may
	// re-execute the sub-select once per candidate row and delete far more
	// than n rows.
	s.pruneSQL = `
WITH victims AS MATERIALIZED (
	SELECT id FROM ` + t + `
	 WHERE state = 'published'
	   AND published_at < now() - make_interval(secs => $1)
	 ORDER BY published_at
	 LIMIT $2
	   FOR UPDATE SKIP LOCKED
)
DELETE FROM ` + t + ` m
 USING victims v
 WHERE m.id = v.id AND m.state = 'published'`

	s.listFailedSQL = `SELECT id, event_type, attempts, updated_at,
       coalesce(last_error, ''), coalesce(last_error_kind, ''),
       aggregate_type, aggregate_id, coalesce(ordering_key, '')
  FROM ` + t + `
 WHERE state = 'failed'
   AND ($2::uuid IS NULL OR seq > coalesce((SELECT seq FROM ` + t + ` WHERE id = $2::uuid), 0))
 ORDER BY seq
 LIMIT $1`
}

// Statement is a SQL statement with its bind parameters, as produced by
// [Store.EnqueueStatements].
type Statement struct {
	Query string
	Args  []any
}

// Enqueue inserts messages using tx, which must be the transaction that
// carries the business change. The insert commits with that transaction or not
// at all; that single fact is the whole point of the outbox pattern.
//
// Messages with a zero ID are assigned a UUIDv7. The generated value is not
// reported back, so set [outbox.Message.ID] yourself (with [outbox.NewID]) if
// you need to know it, for example to log it or to reuse it as a broker
// deduplication key.
//
// Large batches are split across several INSERT statements, all on tx, so
// atomicity is unaffected. Passing no messages is a no-op.
//
// Enqueue never blocks on a broker, never starts its own transaction, and does
// no work beyond the insert: publishing happens later, in the worker.
func (s *Store) Enqueue(ctx context.Context, tx outbox.Execer, msgs ...outbox.Message) error {
	if len(msgs) == 0 {
		return nil
	}
	if tx == nil {
		return errors.New("outbox/postgres: a transaction (or *sql.DB) is required to enqueue")
	}
	stmts, err := s.EnqueueStatements(msgs...)
	if err != nil {
		return err
	}
	for _, st := range stmts {
		if _, err := tx.ExecContext(ctx, st.Query, st.Args...); err != nil {
			return fmt.Errorf("outbox/postgres: insert into %s: %w", s.table, err)
		}
	}
	return nil
}

// EnqueueStatements renders the INSERT statements [Store.Enqueue] would
// execute. It exists for applications that do not use database/sql — a
// pgx.Tx, for example — and want to run the inserts on their own transaction
// handle. Every value is a bind parameter.
func (s *Store) EnqueueStatements(msgs ...outbox.Message) ([]Statement, error) {
	// The per-column casts make the statement unambiguous for drivers that
	// send parameters as untyped text, and let NULL select the column default.
	const cols = enqueueColumns

	var out []Statement
	for chunk := range chunks(msgs, s.maxBatch) {
		var b strings.Builder
		b.WriteString("INSERT INTO ")
		b.WriteString(s.table)
		b.WriteString(" (id, event_type, payload, content_type, headers," +
			" aggregate_type, aggregate_id, ordering_key, available_at) VALUES ")
		args := make([]any, 0, len(chunk)*cols)
		for i, m := range chunk {
			if err := m.Validate(); err != nil {
				return nil, err
			}
			if m.ID.IsZero() {
				m.ID = outbox.NewID()
			}
			headers := "{}"
			if len(m.Headers) > 0 {
				raw, err := json.Marshal(m.Headers)
				if err != nil {
					return nil, fmt.Errorf("%w: headers of %s are not serialisable: %w",
						outbox.ErrInvalidMessage, m.ID, err)
				}
				headers = string(raw)
			}
			payload := m.Payload
			if payload == nil {
				payload = []byte{}
			}
			if i > 0 {
				b.WriteString(", ")
			}
			b.WriteByte('(')
			for c, cast := range enqueueCasts {
				b.WriteByte('$')
				b.WriteString(strconv.Itoa(i*cols + c + 1))
				b.WriteString(cast)
				b.WriteString(", ")
			}
			// A zero AvailableAt means "available now", decided by the
			// database so that it uses the same clock as everything else. A
			// value in the past is clamped to now: it is immediately
			// claimable either way, and keeping a historical timestamp would
			// make a backfill look like a huge publishing backlog.
			b.WriteString("greatest(coalesce($")
			b.WriteString(strconv.Itoa(i*cols + cols))
			b.WriteString("::timestamptz, now()), now()))")

			args = append(args,
				m.ID,
				m.Type,
				payload,
				m.ContentType,
				headers,
				m.AggregateType,
				m.AggregateID,
				nullString(m.OrderingKey),
				nullTime(m.AvailableAt),
			)
		}
		out = append(out, Statement{Query: b.String(), Args: args})
	}
	return out, nil
}

func nullString(s string) any {
	if s == "" {
		return nil
	}
	return s
}

func nullTime(t time.Time) any {
	if t.IsZero() {
		return nil
	}
	return t.UTC()
}

// chunks yields successive chunks of at most n elements.
func chunks[T any](s []T, n int) func(func([]T) bool) {
	if n <= 0 {
		n = len(s)
	}
	return func(yield func([]T) bool) {
		for i := 0; i < len(s); i += n {
			end := min(i+n, len(s))
			if !yield(s[i:end]) {
				return
			}
		}
	}
}
